## 3️⃣  Suggested Refactor (minimal yet secure)

Below is a **drop‑in** rewrite that addresses the most critical issues while keeping the original behaviour.

```js
// app.js – Hardened version
// ------------------------------------------------
// Security‑focused minimal Express server
//------------------------------------------------

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
// Optional: logging
const morgan = require('morgan');

const app = express();

// ---------- Middleware ----------
app.use(helmet()); // Sets a sensible set of security headers

// CORS – restrict to known origins (fallback to same‑origin)
const allowedOrigins = (process.env.ALLOWED_ORIGINS || '').split(',').filter(Boolean);
app.use(
  cors({
    origin: allowedOrigins.length ? allowedOrigins : (origin, cb) => cb(null, true), // * for dev
    methods: ['GET'],
  })
);

// Rate limiting – protect against brute‑force / DoS
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 min
  max: 100, // max 100 requests per window per IP
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(apiLimiter);

// Simple request logging (helps with audit)
app.use(morgan('combined'));

// ---------- Routes ----------
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  // NOTE: In a real production app this data would be protected!
  const users = [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];
  res.json(users);
});

// ---------- Error handling ----------
app.use((err, _req, res, _next) => {
  // Log the error (could be sent to a monitoring service)
  console.error(err);
  const status = err.status || 500;
  const response = {
    error: status === 500 ? 'Internal Server Error' : err.message,
  };
  // In production hide stack traces
  if (process.env.NODE_ENV !== 'production') {
    response.stack = err.stack;
  }
  res.status(status).json(response);
});

