// config.js
const requiredVars = {
  // category → { envName: regex, description }
  aws: {
    AWS_ACCESS_KEY_ID: /^AKIA[0-9A-Z]{16}$/,
    AWS_SECRET_ACCESS_KEY: /^[0-9a-zA-Z/+]{40}$/,
  },
  stripe: {
    STRIPE_SECRET_KEY: /^sk_live_[0-9a-zA-Z]{24}$/,
    STRIPE_PUBLISHABLE_KEY: /^pk_live_[0-9a-zA-Z]{24}$/,
