  },
  db: {
    DATABASE_URL: /^postgresql:\/\/[^:]+:[^@]+@[^:]+:\d+\/[^?]+/,
  },
  // add more groups as needed…
};

function validateEnv() {
  for (const [group, vars] of Object.entries(requiredVars)) {
    for (const [name, pattern] of Object.entries(vars)) {
      const value = process.env[name];
      if (!value) {
        throw new Error(`[config] Missing required env var ${name} (group: ${group})`);
      }
      if (!pattern.test(value)) {
        throw new Error(
          `[config] Invalid format for ${name}: "${value}". Expected pattern ${pattern}`
        );
      }
    }
  }
}

